import type { Candidate, Confidence, Inscription, SourceRecord } from '#lib/types.ts';

export interface RawPerson {
	name: string;
	born: string | null;
	died: string | null;
}

export interface RawMatch {
	id: string;
	born: string | null;
	died: string | null;
	place: string | null;
	confidence: Confidence;
}

export interface RawFact {
	claim: 'name' | 'birth' | 'death' | 'other';
	sourceId: string;
	quote: string;
}

export interface PageText {
	sourceId: string;
	text: string;
}

export interface InferenceProvider {
	readStone(image: Uint8Array, mimeType: string): Promise<RawPerson[]>;
	pickMatches(inscription: Inscription, records: SourceRecord[]): Promise<RawMatch[]>;
	extractFacts(
		inscription: Inscription,
		candidate: Candidate,
		pages: PageText[]
	): Promise<RawFact[]>;
	tellStory(name: string, facts: string[]): Promise<string>;
}
	id: string;
	url: string;
	title: string;
	site: string;
	snippet: string;
}

/** How sure the match is that the records are about the stone's person. */
export type Confidence = 'high' | 'medium' | 'low';

/** One hypothesized person with the records that support it. */
export interface Candidate {
	name: string;
	born: string | null;
	died: string | null;
	place: string | null;
	confidence: Confidence;
	sources: SourceRecord[];
}

export type Story =
	{ status: 'told'; paragraph: string; sources: SourceRecord[] } | { status: 'insufficient' };

export interface ApiError {
	error: {
		code: 'invalid_input' | 'unsupported_type' | 'too_large' | 'provider_failed';
		message: string;
	};
}
